    while(i<repeat){
        large=0;
        j=0;
        index=0;
        for(vector<string> row : stat_matrix){
            if(stoi(row[2])> large){
                large = stoi(row[2]);
                index = j;
            }
            j++;
        }
        value.push_back(stat_matrix[index]);
        stat_matrix.erase(stat_matrix.begin()+index);
        i++;
    }
    return value;
