string input_validation(string input, int code, bool &flag){
    if(code == 1){
        int integer;
        try{
            integer = stoi(input);
            if(input.length()!= to_string(integer).length())
                {throw runtime_error("");}
            flag = 1;
            user_input<int> = integer;
        }catch(...){
            return "Please enter an integer number\n";
        }
    }
    else if(code == 2){
        double fraction;
        try{
            fraction = stod(input);
            ostringstream element;
            element<<fraction;
            string placeholder = element.str();
            if(input.length()!= placeholder.length())
                {throw runtime_error("");}
            flag = 1;
            user_input<double> = fraction;
        }catch(...){
            return "Please enter a float number(decimal number)\n";
        }
    }
    else if(code == 3){
        try{
            int x = stoi(input);
            return "Enter a character letter, not a number\n";

        }
        catch(...){
            if(input.length() > 1){return "Please enter a single character\n";}
            else{
                flag=1;
                user_input<char> = input[0];
            }
        }
    }
    else{
        cout<<"System Error";
        exit(1);
    }
    return "";
}
void input(int code, string text = ""){
    // check guide: 1 for int, 2 for double, 3 for char
    string value, clean_value; // value with no spaces;
    string message;
    bool flag = 0;
    do{
        clean_value = "";
        getline(cin,value);
        for(char c : value){
            if(c != ' '){clean_value += c;}
        }
        message = input_validation(clean_value, code, flag);
        if(!flag){
            ConsoleColor::red();
            cout<<message;
            cout<<text<<":";
            ConsoleColor::reset_color();
        }
    }while(!flag);
    return;
}

