string to_lower(string s){
    string holder = {};
    for(char c:s){holder += tolower(c);}
    return holder;
}
string cleaner(string input){ // replace commas with space and remove extra spaces
    string output;
    int check1 = 0, check2 = 0;
    for(char c:input){
        if(c == ' ' && !check2){
            check2 = 1;
            check1 = 1;
            continue;
        }
        if(c == ','){
            output += ' ';
            check1=1;
        }
        else{
            if(check1 && c == ' '){
                continue;
            }
            else if(c==' '){
                check1=1;
                output += c;
            }
            else{
                check1 = 0;
                output += c;
            }
        }
    }
    while(!output.empty() && output.front() == ' ')
        output.erase(output.begin());
    while(!output.empty() && output.back() == ' ')
        output.pop_back();
    return output;
}
int search(string name){
    memory();
    int i = 0;
    for(vector<string> row: matrix){
        if(to_lower(row[0]) == to_lower(name)){
            return i;
        }
        i++;
    }
    return -1;//indicates that the file doesn't exist
}
void memory(){
    ifstream file("../data/inventory.txt");
    if(!file){
        cout<<"System Error";
        exit(1);
    }
    string line;
    matrix = {};  // clear global matrix

    while (getline(file, line)) {
        vector<string> row;
        istringstream elements(line);
        string field;
        while (getline(elements, field, ',')) {  // split line by comma
            row.push_back(field);
        }
        matrix.push_back(row);
    }

    file.close();
}
