void deleter(string value){
    int index = search(value);
    if(index>=0){
        matrix.erase(matrix.begin()+index);
        cout<<"Product has been remove\n";
    }
    else{cout<<"The product was not found\n";}
    fileset();
}
void inserter(product item){
    ostringstream element;
    element<<item.price;
    string placeholder = element.str();
    vector<string> row = {item.name,placeholder,to_string(item.stock)};
    matrix.push_back(row);
    sorter();
}
void fileset(){
    ofstream file("../data/inventory.txt");
    int j=0;
    for(vector<string> row : matrix){
        for(string element : row){
            file<<element;
            if(j<row.size()-1){file<<',';}
            j++;
        }
        j=0;
        file<<'\n';
    }
    file.close();
}
void sorter(){
    vector<string> temp;
    int flag;
    do{
        flag = 0;
        for(int i=1;i<matrix.size();i++){
            for(int j=0;j<matrix[i].size();j++){
                if(to_lower(matrix[i-1][0][j] + string(""))[0] > to_lower(matrix[i][0][j] + string(""))[0]){
                    temp = matrix[i-1];
                    matrix[i-1] = matrix[i];
                    matrix[i] = temp;
                    flag = 1;
                    break;
                }
                else if(to_lower(matrix[i-1][0][j] + string(""))[0] < to_lower(matrix[i][0][j] + string(""))[0]){
                    break;
                }
            }
        }
    }while(flag);
    fileset();
}
