void exp_product_log(int index){
    if (index < 0 || index >= exp_matrix.size())
        return;
    ofstream file("../data/expired_goods.txt", ios::app);
    if (!file)
        return;
    const auto& row = exp_matrix[index];
    for (int i = 0; i < row.size(); i++) {
        file << row[i];
        if (i + 1 < row.size())
            file << ",";
    }
    file << "\n";
    file.close();
}
