    else if(code == 2){
        double fraction;
        try{
            fraction = stod(input);
            ostringstream element;
            element<<fraction;
            string placeholder = element.str();
            if(input.length()!= placeholder.length())
                {throw runtime_error("");}
            flag = 1;
            user_input<double> = fraction;
        }catch(...){
            return "Please enter a float number(decimal number)\n";
        }
    }
    else if(code == 3){
        try{
            int x = stoi(input);
            return "Enter a character letter, not a number\n";

        }
        catch(...){
            if(input.length() > 1){return "Please enter a single character\n";}
            else{
                flag=1;
                user_input<char> = input[0];
            }
        }
    }
    else{
        cout<<"System Error";
        exit(1);
    }
    return "";
